// soc.h, generated by RVisio from the SoC configuration "SoC: Flash + SRAM + DRAM, UART, SPI, I2C, GPIO, timer, sensor" (do not edit by hand).
// Addresses and registers of memories and peripherals. For another board (e.g. the one your teacher
// assigned to you) download its soc.h in RVisio: SoC → 📘 VS Code guide → Materials → soc.h.
#pragma once
#include <stdint.h>

#define REG32(a) (*(volatile uint32_t *)(a))

// ---- memories
#define FLASH_BASE 0x00000000  // Flash, read-only
#define FLASH_SIZE 0x00010000
#define SRAM_BASE 0x00010000  // SRAM
#define SRAM_SIZE 0x00010000
#define DRAM_BASE 0x00100000  // DRAM
#define DRAM_SIZE 0x00100000

// ---- system I/O (console and program exit)
#define SYSIO_PUTCHAR REG32(0x00400000)
#define SYSIO_EXIT    REG32(0x00400004)

// ---- uart0 (UART), interrupt 0
#define UART0_BASE 0x00800000
#define UART0_IRQ  0
#define UART0_TXDATA REG32(UART0_BASE + 0x00)  // W: byte to transmit
#define UART0_RXDATA REG32(UART0_BASE + 0x04)  // R: received byte
#define UART0_STATUS REG32(UART0_BASE + 0x08)  // bit0 TX busy, bit1 RX data available, bit2 TX FIFO full
#define UART0_CTRL REG32(UART0_BASE + 0x0c)  // bit0 interrupt on receive, bit1 interrupt when transmission is done, bit2 RTS/CTS flow control
#define UART0_BAUDDIV REG32(UART0_BASE + 0x10)  // cycles per bit

// ---- spi0 (SPI), interrupt 1
#define SPI0_BASE 0x00801000
#define SPI0_IRQ  1
#define SPI0_DATA REG32(SPI0_BASE + 0x00)  // W: send a byte, R: received byte
#define SPI0_STATUS REG32(SPI0_BASE + 0x04)  // bit0 busy, bit1 transfer done
#define SPI0_CTRL REG32(SPI0_BASE + 0x08)  // bit0 CS active, bit1 interrupt
#define SPI0_CLKDIV REG32(SPI0_BASE + 0x0c)  // cycles per bit

// ---- i2c0 (I2C), interrupt 2
#define I2C0_BASE 0x00802000
#define I2C0_IRQ  2
#define I2C0_ADDR REG32(I2C0_BASE + 0x00)  // 7-bit address << 1 | R/W
#define I2C0_DATA REG32(I2C0_BASE + 0x04)  // byte
#define I2C0_CMD REG32(I2C0_BASE + 0x08)  // 1 START, 2 WRITE, 3 READ+ACK, 4 READ+NACK, 5 STOP
#define I2C0_STATUS REG32(I2C0_BASE + 0x0c)  // bit0 busy, bit1 NACK, bit2 done
#define I2C0_CLKDIV REG32(I2C0_BASE + 0x10)
#define I2C0_CTRL REG32(I2C0_BASE + 0x14)  // bit0 interrupt

// ---- gpio0 (GPIO), interrupt 3
#define GPIO0_BASE 0x00803000
#define GPIO0_IRQ  3
#define GPIO0_OUT REG32(GPIO0_BASE + 0x00)  // outputs (LEDs)
#define GPIO0_IN REG32(GPIO0_BASE + 0x04)  // inputs (buttons)
#define GPIO0_DIR REG32(GPIO0_BASE + 0x08)
#define GPIO0_IRQ_EN REG32(GPIO0_BASE + 0x0c)  // interrupt on input change
#define GPIO0_IRQ_STATUS REG32(GPIO0_BASE + 0x10)  // write 1 to clear

// ---- timer0 (TIMER), interrupt 4
#define TIMER0_BASE 0x00804000
#define TIMER0_IRQ  4
#define TIMER0_LOAD REG32(TIMER0_BASE + 0x00)
#define TIMER0_VALUE REG32(TIMER0_BASE + 0x04)  // R
#define TIMER0_CTRL REG32(TIMER0_BASE + 0x08)  // bit0 enabled, bit1 periodic, bit2 interrupt
#define TIMER0_STATUS REG32(TIMER0_BASE + 0x0c)  // bit0 expired, write 1 to clear
#define TIMER0_PRESCALE REG32(TIMER0_BASE + 0x10)

// ---- intc (INTC)
#define INTC_BASE 0x00805000
#define INTC_PENDING REG32(INTC_BASE + 0x00)  // R
#define INTC_ENABLE REG32(INTC_BASE + 0x04)
#define INTC_CLAIM REG32(INTC_BASE + 0x08)  // R: number+1 of the lowest active interrupt, 0 = none
#define INTC_SOFT REG32(INTC_BASE + 0x0c)  // software interrupt 31: write 1 = request, 0 = clear

// ---- sensor0 (CUSTOM), interrupt 5
#define SENSOR0_BASE 0x00806000
#define SENSOR0_IRQ  5
#define SENSOR0_DATA REG32(SENSOR0_BASE + 0x00)  // ro: last measured value
#define SENSOR0_STATUS REG32(SENSOR0_BASE + 0x04)  // w1c: bit0: new data (write 1 to clear)
#define SENSOR0_CTRL REG32(SENSOR0_BASE + 0x08)  // rw: bit0: interrupt enable
#define SENSOR0_TICKS REG32(SENSOR0_BASE + 0x0c)  // counter: counts cycles since reset

// ---- uart1 (UART), interrupt 6
#define UART1_BASE 0x00807000
#define UART1_IRQ  6
#define UART1_TXDATA REG32(UART1_BASE + 0x00)  // W: byte to transmit
#define UART1_RXDATA REG32(UART1_BASE + 0x04)  // R: received byte
#define UART1_STATUS REG32(UART1_BASE + 0x08)  // bit0 TX busy, bit1 RX data available, bit2 TX FIFO full
#define UART1_CTRL REG32(UART1_BASE + 0x0c)  // bit0 interrupt on receive, bit1 interrupt when transmission is done, bit2 RTS/CTS flow control
#define UART1_BAUDDIV REG32(UART1_BASE + 0x10)  // cycles per bit
